MORE.update({'dmitrov': {'hist': ['Дмитров считается основанным в 1154 году Юрием Долгоруким: князь назвал город в честь новорождённого сына Всеволода, в крещении Дмитрия, — будущего Всеволода Большое Гнездо.', 'По легенде, кремль заложили на болоте, и дмитровчан до революции шутливо звали «лягушатниками». В 1781 году город стал центром уезда, а в 1930-х через него прошёл канал имени Москвы.'], 'extra': [('Дом-музей Кропоткина', 'Особняк XIX века, где жил географ и теоретик анархизма Пётр Кропоткин.'), ('Мемориал защитникам Москвы', 'На холме над каналом у въезда в город с юга — памятник бойцу Красной Армии.')], 'food': [('Вишнёвый сад', 'Кафе и ресторан', 'Кропоткинская ул., 75А', 'https://yandex.ru/maps/org/vishnyovy_sad/208037811152/'), ('Грядка', 'Столовая, недорого', 'Загорская ул., 30', 'https://yandex.ru/maps/org/gryadka/29435515374/'), ('Кофе-Тайм', 'Кофейня', 'Кропоткинская ул., 59А', 'https://yandex.ru/maps/org/kofe_taym/1214596435/'), ('Бисквит', 'Ресторан', 'Московская ул., 27А', 'https://yandex.ru/maps/org/biskvit/80720984393/'), ('Старик Хинкалыч', 'Ресторан', 'Профессиональная ул., 6', 'https://yandex.ru/maps/org/starik_khinkalych/218953981385/')], 'hsrc': [('За рулём: на выходные в Дмитров', 'https://www.zr.ru/content/articles/950525-na-vykhodnye-v-dmitrov-7-prichi/')]}, 'muranovo': {'hist': ['История Мураново как усадьбы начинается в 1645 году. В первой половине XIX века ею владели Энгельгардты и их зять, поэт Евгений Боратынский.', 'В 1869 году усадьба досталась в приданое Ольге Путяте, вышедшей замуж за Ивана, старшего сына поэта Фёдора Тютчева. Сам Тютчев здесь ни разу не был, но после его смерти в Мураново перевезли его вещи и рукописи. Музей открылся после революции, первым директором стал внук поэта Николай Тютчев.'], 'extra': [('Абрамцево', 'Соседняя усадьба Мамонтова — по той же Ярославской дороге.')], 'food': [('В амбаре', 'Кафе на территории усадьбы', 'музей-заповедник «Мураново»', 'https://yandex.ru/maps/org/v_ambare/1683282264/'), ('Кафетерий', 'Кофейня', 'Ашукино, Школьная ул., 1', 'https://yandex.ru/maps/org/kafeteriy/63262051557/')], 'hsrc': []}, 'ostafevo': {'hist': ['Современный облик Остафьево начало приобретать в 1792 году, когда усадьбу купил князь Андрей Вяземский. Почти двенадцать лет, с 1804 по 1815 год, здесь жил историограф Николай Карамзин и написал восемь томов «Истории государства Российского».', 'При поэте Петре Вяземском сюда приезжали Пушкин, Гоголь, Батюшков, Грибоедов, Денис Давыдов и Адам Мицкевич — Вяземский называл усадьбу «Русским Парнасом». В 2010–2016 годах дом отреставрировали.', 'Дубровицы купил в 1688 году князь Борис Голицын. Попав в опалу, он вскоре вернул расположение Петра I и в 1690 году заложил храм Знамения — необычный для Руси, в духе европейского барокко.'], 'extra': [('Подольск', 'Краеведческий музей и набережная Пахры по дороге в Дубровицы.')], 'food': [('Сударушка', 'Кафе', 'посёлок Фабрики имени 1 Мая, 4', 'https://yandex.ru/maps/org/sudarushka/1739168292/')], 'hsrc': [('mos.ru: «Русский Парнас»', 'https://www.mos.ru/news/item/109226073/')]}, 'tarusa-polenovo': {'hist': ['Таруса — один из старейших городов на Оке. В XX веке она стала «городом художников и писателей»: здесь жили и работали Паустовский, бывала Цветаева, на берегу Оки писали этюды живописцы.', 'Художник Василий Поленов построил усадьбу на высоком берегу напротив Тарусы в 1890-х и задумал её как музей для местных жителей. Сам он называл эти места «заповедником русского пейзажа».'], 'extra': [('Велегож и Ланьшино', 'Окские деревни недалеко от Тарусы, автобусы ходят с местного автовокзала.')], 'food': [('Дядя Дымов', 'Ресторан', 'Таруса, ул. Карла Либкнехта, 11/20', 'https://yandex.ru/maps/org/dyadya_dymov/226862171124/'), ('Тарусское время', 'Кафе', 'Таруса, ул. Луначарского, 13/6', 'https://yandex.ru/maps/org/tarusskoye_vremya/1363837107/'), ('Доброе утро', 'Кафе', 'Таруса, ул. Каляева, 4', 'https://yandex.ru/maps/org/dobroye_utro/48191092932/'), ('Где-то здесь', 'Кафе и кофейня', 'Таруса, Октябрьская ул., 6', 'https://yandex.ru/maps/org/gde_to_zdes/12409145514/'), ('Голубчики', 'Ресторан', 'Таруса, ул. Ленина, 22', 'https://yandex.ru/maps/org/golubchiki/114254583347/'), ('Маруся', 'Ресторан', 'Таруса, пл. Ленина, 4', 'https://yandex.ru/maps/org/marusya/152323788575/')], 'hsrc': [('Travelask: Таруса', 'https://travelask.ru/russia/tarusa')]}})

