MORE.update({'serpuhov': {'hist': ['Официальной датой основания считают 1339 год — Серпухов упомянут в завещании Ивана Калиты. Деревянный кремль в 1374 году поставил князь Владимир Храбрый, чтобы прикрыть Сенькин брод через Оку.', 'Коллекция живописи серпуховской фабрикантши Анны Мараевой после революции стала основой городского музея — он открылся в 1920 году.'], 'extra': [('Принарский парк', 'Набережная Нары с плотиной-водопадом; хорошо видна от Высоцкого монастыря.'), ('Павлины', 'Птица с городского герба: её скульптуры расставлены по улицам.'), ('Заповедник с зубрами', 'Приокско-Террасный заповедник — в получасе езды от Серпухова.')], 'food': [], 'hsrc': []}, 'borovsk': {'hist': ['Боровск остаётся значимым местом для старообрядцев: в Пафнутьевом монастыре дважды держали в заточении протопопа Аввакума.', 'В Боровске учительствовал Константин Циолковский — отсюда музей-квартира и памятник на пешеходной Театральной улице, где учёный смотрит в небо.'], 'extra': [('Смотровая на Высоком', 'У «Чайной на Высоком» и памятника Пафнутию Боровскому — вид на город и долину Протвы.'), ('Этномир', 'Этнографический парк по соседству.'), ('Парк птиц «Воробьи»', 'В том же направлении от Москвы.')], 'food': [], 'hsrc': []}, 'mozhaysk-borodino': {'hist': ['В летописях Можайск впервые упомянут под 1231 годом. От его кремля остались валы и фрагменты стен.', 'Бородинское сражение произошло в 12 километрах от города в 1812 году. Французы устроили в Лужецком монастыре штаб, а Никольский собор разграбили.'], 'extra': [('Можайское водохранилище', '«Можайское море» в нескольких километрах от города — летом сюда едут купаться.'), ('Высота Рубо', 'Место на поле, откуда Франц Рубо писал Бородинскую панораму.')], 'food': [], 'hsrc': []}, 'egorevsk': {'hist': ['Город учреждён указом Екатерины II в 1778 году на месте села Высокое, известного с 1462 года.', 'В XIX веке Егорьевск подняли текстильные фабриканты Хлудовы и Бардыгины: на их деньги замостили улицы, провели водопровод и освещение, построили училища, собор и монастырь.'], 'extra': [('Алексиевский храм', 'Улица Нечаевская, 1908 год.'), ('Хлудовское училище', 'Здание 1895 года на улице Парижской Коммуны, сейчас гимназия.'), ('Парк «200 лет Егорьевску»', 'Обновлённый городской парк, площадка праздников.')], 'food': [], 'hsrc': []}, 'klin': {'hist': ['Чайковский поселился в доме на окраине Клина в мае 1892 года и прожил здесь до октября 1893-го. Уже через год его брат Модест открыл в доме музей.', 'Стеклянные ёлочные игрушки в Клинском уезде начали делать в XIX веке; в 1987 году мелкие фабрики объединили в предприятие «Ёлочка».'], 'extra': [('Что привезти', 'Ёлочные игрушки, сувениры из музея Чайковского, местные сыры и масло.')], 'food': [], 'hsrc': []}, 'monino': {'hist': ['Музей основан в 1958 году на месте бывшего аэродрома Монино, а первых посетителей принял в 1960-м. Сюда на вечную стоянку отправляют самолёты и вертолёты, отслужившие своё.'], 'extra': [], 'food': [], 'hsrc': []}, 'senezh': {'hist': ['Маленькое ледниковое озеро превратилось в большое водохранилище в первой четверти XIX века, когда строили Екатерининский канал между реками Сестрой и Истрой. Старый Сенеж остался одним из заливов.', 'Здесь писал эскизы к своей последней, неоконченной картине «Озеро» Исаак Левитан. В 1945 году на берегу построили Дом художников, а в 1960-х работала студия дизайна «Сенеж».'], 'extra': [('Середниково', 'Усадьба и киногород в том же городском округе — можно совместить.')], 'food': [], 'hsrc': []}, 'gorki-leninskie': {'hist': ['Усадьба известна с XVIII века и сменила многих владельцев. В 1909 году её купила Зинаида Морозова-Рейнбот; перестройку дома часто приписывают Фёдору Шехтелю, но это только версия.', 'После революции Горки стали резиденцией Ленина: он жил здесь в 1920–1924 годах и здесь умер. Дом-музей открыли в январе 1949 года.'], 'extra': [('Траурная аллея', 'Памятник «Похороны вождя» — редкий монумент, посвящённый смерти Ленина.'), ('Аллея монументальной пропаганды', 'Бюсты и памятники Ленину, Сталину и Марксу, свезённые сюда в 1990-х.'), ('Музей крестьянского быта', 'Изба в деревне Горки, где в 1921 году Ленин встречался с крестьянами.')], 'food': [], 'hsrc': []}, 'pereslavl-zalesskiy': {'hist': ['Переславль основал Юрий Долгорукий в 1152 году — на пять лет позже Москвы. Здесь родился Александр Невский.', 'Шестнадцатилетним на Плещеево озеро приехал Пётр I и вскоре начал строить здесь потешную флотилию. От неё уцелел один бот — «Фортуна».'], 'extra': [('Троице-Данилов монастырь', 'Троицкий собор с фресками XVII века.'), ('Музей хитростей и смекалки', 'Старые бытовые вещи, среди которых утюги для манжет и шляп.'), ('Сергиев Посад', 'По дороге из Москвы — можно остановиться у Лавры.')], 'food': [], 'hsrc': []}, 'rostov-velikiy': {'hist': ['Ростов упоминается с IX века — он на три столетия старше Москвы. Великим его стали называть в начале XIII века, когда город был столицей Ростовского княжества.', 'Кремль, который видят сегодня, построили во второй половине XVII века как резиденцию митрополита.'], 'extra': [('Церковь Исидора Блаженного', 'Построена в 1566 году по приказу Ивана Грозного.'), ('Троице-Варницкий монастырь', 'На месте рождения Сергия Радонежского, за городом.'), ('«Лукова слобода»', 'Кафе-музей ростовского лука.')], 'food': [], 'hsrc': []}, 'uglich': {'hist': ['Основателем Углича предание называет Яна Плесковича, родственника княгини Ольги, а датой — 937 год.', 'В 1591 году в угличском кремле погиб малолетний царевич Димитрий, младший сын Ивана Грозного. С этой историей связывают конец династии и начало Смуты.', 'План Угличской ГЭС был готов к 1940 году; она стала первой гидроэлектростанцией на Волге.'], 'extra': [('Спасо-Преображенский собор', 'Начало XVIII века, росписи появились столетием позже.'), ('Богоявленский монастырь', 'Улица Студенческий городок, 12.'), ('Мышкин', 'Маленький город на Волге в часе езды на автобусе.')], 'food': [], 'hsrc': []}})
LONG.update({'serpuhov': [('Что посмотреть подробно', [('«Малая Третьяковка»', 'Серпуховский музей считают крупнейшей картинной галереей Подмосковья. Он занимает усадьбу Мараевых: сам особняк работы Клейна — половина впечатления. Основа собрания — коллекция Анны Мараевой; среди самых ценных разделов — живопись и графика Натальи Гончаровой.'), ('Высоцкий монастырь', 'Одна из девяти обителей, основанных Сергием Радонежским. Стоит на высоком берегу Нары — отсюда название. Икона «Неупиваемая чаша» хранится в Покровском храме.'), ('Владычный монастырь', 'По преданию, именно здесь впервые была явлена «Неупиваемая чаша». На стенах обоих монастырей — редкие мозаичные иконы.'), ('Соборная гора', 'От белокаменного кремля остались небольшие куски стены; сюда приходят ради вида на город.')]), ('Что попробовать и привезти', [('', 'Серпуховскую помадку — сладость на меду, которую в XIX веке придумала та же купчиха Мараева; её рецепт хранится в поварской книге в музее. Чай местного завода — около ста сортов. И павлина: керамического, деревянного или металлического.')])], 'borovsk': [('Что посмотреть подробно', [('Росписи', 'Это не муралы в привычном смысле: художник-пенсионер Владимир Овчинников писал на стенах реальных жителей, события и виды старого Боровска. На торце «Дома с ангелами» — Фёдор Конюхов в облачении священника. От этого дома можно спуститься к Протве.'), ('Музей Циолковского', 'Экскурсоводы показывают опыты учёного, в том числе шуточный «чай с невидимым вареньем» на электростатической машине. Многое разрешают трогать.'), ('«Дом самолёта Як-40»', 'Помимо музея на территории есть домики, кемпинг для автодомов, прокат сапов и катамаранов.'), ('Пафнутьев монастырь', 'Стоит отдельно от исторического центра, удобнее доехать на машине. Читатели Т—Ж называют его лучшим, что есть в городе.')]), ('Где поесть и что купить', [('', '«Чайная на Высоком» — с видом на город, средний чек около 1000 ₽; приходите до обеда, позже часть блюд заканчивается. В лавке «Домик счастья» продают калужский мармелад (200–300 ₽), козельское мороженое и тыквейн — тёплый напиток на тыквенном сиропе (250 ₽). Цены — на апрель 2026 года.')]), ('Сколько стоит день', [('', 'Автор Т—Ж потратила 4800 ₽: примерно половину на сувениры и выпечку, остальное на экскурсии, еду и дорогу.')])], 'mozhaysk-borodino': [('Что посмотреть подробно', [('Ново-Никольский собор', 'Первый Никольский собор стоял в кремле ещё до 1541 года. Нынешний украшен не только крестами: на фасадах — шестиконечные звёзды, пирамиды с шарами и треугольники. Территория открыта с 6:00 до 22:00, вход свободный.'), ('Петропавловская церковь', 'Вторая церковь на кремлёвском холме. В 1812 году её разграбили и сожгли французы, восстановили к 1852 году.'), ('Бородинское поле', 'Музей-заповедник — это памятники полкам, братские могилы, уцелевшие укрепления и техника. В музее показывают личные вещи Наполеона и Кутузова и трофеи с поля боя.'), ('Спасо-Бородинский монастырь', 'Вдова генерала Тучкова построила его в память о муже; позже обители покровительствовала царская семья.')]), ('Как уложиться в день', [('', 'На «Ласточке» в 7:15 с Белорусского вокзала вы в Можайске к половине девятого (расписание Яндекс Путешествия приводят на июнь 2024 года). Город занимает полдня, потом — такси или автобус до Бородина. Обратная «Ласточка» уходит вечером.')])], 'egorevsk': [('Что посмотреть подробно', [('Музей', 'Михаил Бардыгин собирал «русскую старину» и подарил музей городу. Экспозиции интерактивные, со светом и звуком. Здесь же можно послушать «предсказания» юродивого Корейши.'), ('Собор Александра Невского', 'Поводом стало покушение на Александра II: сначала поставили часовню, затем собор. В 2010 году началась реставрация, восстановлены росписи.'), ('Георгиевский храм', 'Самый большой действующий старообрядческий храм России; сейчас его реставрируют.'), ('Соборная площадь', 'Памятник Ленину 1927 года стоит на месте Успенского собора, взорванного в 1937 году.')]), ('Откуда название', [('', 'По одной версии — от Георгия Победоносца. По другой, шуточной: здешние жители не платили дань сборщикам трёх соседних княжеств, то есть «объегоривали» их.')])], 'klin': [('Что посмотреть подробно', [('Дом Чайковского', 'Последний дом композитора: главный экспонат — его рояль «Беккер». В музейной лавке продают музыкальные часы в виде скрипки и веера со «Щелкунчиком».'), ('«Клинское подворье»', 'Музей работает при фабрике. В фирменном салоне выбор игрушек больше, чем в городских лавках.'), ('Дом Гайдара', 'Дом, который писатель снял в 1938 году; здесь написаны «Тимур и его команда» и «Чук и Гек».')]), ('Когда ехать', [('', 'Летом — на фестиваль Чайковского. В мае в Клину проводят фестиваль воздухоплавания, в марте — народных промыслов. Зимой сюда едут за ёлочными игрушками: перед Новым годом билеты в музей лучше покупать заранее.')])], 'gorki-leninskie': [('Что посмотреть подробно', [('Музей Ленина', 'Его называли первым мультимедийным музеем страны. Здание сложено из простых геометрических объёмов; посетители, по словам сотрудников, порой принимают его за крематорий.'), ('Дом', 'Все часы в доме показывают 18:50 — время смерти Ленина. Хранятся посмертная маска и слепки рук.'), ('«Кабинет и квартира в Кремле»', 'Обстановку кремлёвского кабинета и квартиры семьи Ульяновых перевезли сюда из Сенатского дворца в 1994 году.'), ('Парк', 'Дубу в парке, по данным Tripster, около восьмисот лет. В розарии больше пятидесяти сортов роз. Курганов вятичей в липовой роще — до полусотни.'), ('Киногород', 'Здесь снимали «Адмирала» и «Угрюм-реку». Улицы с декорациями открыты, билет не нужен.')])], 'pereslavl-zalesskiy': [('Что посмотреть подробно', [('Собор и валы', 'Спасо-Преображенский собор — ровесник города. Валы обходят по кругу: сверху видны крыши малоэтажного центра.'), ('«Ботик Петра I»', 'Музей называют старейшим провинциальным музеем России. Кроме самого бота здесь несколько небольших экспозиций, билет на каждую отдельный.'), ('Плещеево озеро', 'Озеро так понравилось юному Петру размерами, что он устроил здесь верфь. Сегодня это национальный парк.'), ('Александрова гора', 'До крещения Руси здесь совершали языческие обряды. Монастырь Александра Невского разорили в Смуту.'), ('Никитский монастырь', 'Его осаждали поляки и разоряли литовцы; восстанавливали обитель при поддержке Романовых.')]), ('На сколько ехать', [('', 'Одним днём успеть можно только центр и ботик. Город тянется вдоль шоссе на десять километров, а монастырей несколько — поэтому путеводители советуют два дня с ночёвкой.')])], 'rostov-velikiy': [('Что посмотреть подробно', [('Кремль', 'Строго говоря, это не крепость, а Архиерейский двор — резиденция ростовских митрополитов. После реставрации он выглядел настолько цельно, что Гайдай снял его вместо московского Кремля.'), ('Ростовские звоны', 'Тринадцать колоколов звонницы вместе дают знаменитые «Ростовские звоны».'), ('Финифть', 'Роспись по эмали — главный ростовский промысел. Собрание музея при фабрике называют крупнейшим в России.'), ('Спасо-Яковлевский монастырь', 'Самый нарядный из ростовских монастырей, на самом берегу. Здесь покоятся мощи Димитрия Ростовского.'), ('Авраамиев монастырь', 'Постройки в основном XVI века и дошли почти без переделок.'), ('Успенский собор', 'По преданию, в 1552 году сюда приезжал Иван Грозный — за Авраамиевым крестом перед походом на Казань.')]), ('Где поесть', [('', 'OneTwoTrip советует «Щучий двор» на улице Достоевского — уха, щучьи котлеты, кулебяка — и «Алёшу Поповича» у музея финифти.')])], 'uglich': [('Что посмотреть подробно', [('Кремль', 'В музей кремля входят палаты, церковь Димитрия, собор и несколько выставок; есть единый билет на все экспозиции.'), ('История царевича', 'На экскурсиях по кремлю рассказывают о гибели Димитрия и о ссыльном колоколе.'), ('Музей гидроэнергетики', 'Один из крупнейших технических музеев страны: об устройстве ГЭС, строительстве Угличской станции и о заключённых Волголага, которые её возводили. Работает со вторника по воскресенье.'), ('Часы и сыр', 'В Угличе работал часовой завод «Чайка», а продукцию местного маслосырзавода везут как сувенир.')]), ('Как добраться без машины', [('', 'По данным Sputnik8, автобус стоит 1500–1800 ₽ и идёт около четырёх часов; билеты через приложение дешевле, чем в кассе. Прямой поезд ходит раз в неделю и идёт почти шесть часов.')])]})

def _dm(x, y, w=20, h=24):   # луковица с крестом на основании (x..x+w, y)
    a = w / 2
    return f'M{x} {y}c0-{h * .43:.1f} {a:g}-{h * .6:.1f} {a:g}-{h} 0 {h * .4:.1f} {a:g} {h * .57:.1f} {a:g} {h}m-{a:g}-{h}v-9m-4 4h8'
def _bx(x, y, w, h): return f'M{x} {y}v-{h}h{w}v{h}'
